#include "domain/longstride_care.hpp"
#include "domain/hero_destination.hpp"
#include "engine/native_population_registry.hpp"
#include <iostream>
using namespace stalthos;using namespace stalthos::fauna;using namespace stalthos::domain;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(){try{
 ActorView adult{77,HeroSpecies::Longstride,{0,0,0},0,7000,0,.1,.1,.1,true,Activity::Travel};ActorView replacement=adult;replacement.id=78;
 LongstrideCare care;need(!care.bindBirth(1,HeroSpecies::Smalltrotter,LifeStage::Hatchling,{3.5,0,0},adult),"Smalltrotter gained care");need(!care.bindBirth(1,HeroSpecies::Longstride,LifeStage::Adult,{3.5,0,0},adult),"adult gained care");need(!care.bindBirth(77,HeroSpecies::Longstride,LifeStage::Hatchling,{3.5,0,0},adult),"self parent");need(care.bindBirth(1,HeroSpecies::Longstride,LifeStage::Hatchling,{3.5,0,0},adult),"actual adult bind");need(!care.bindBirth(2,HeroSpecies::Longstride,LifeStage::Hatchling,{3.5,0,0},replacement),"reparented");
 auto observe=[&](Vec3 body,bool live=true,bool physical=true,bool direct=false,bool goal=false,bool needs=false){return care.observe(1,LifeStage::Hatchling,body,live,physical,direct,goal,needs,{adult,replacement});};
 need(observe({9,0,0}).target.has_value(),"following absent");HeroSim farIntent;auto far=*observe({17,0,0}).target;need(HeroDestination::submit(farIntent,{17,0,0},far,true),"recognized caregiver at17m cannot submit supported follow target within controller radius");need(!observe({3,0,0}).target&&observe({3,0,0}).present,"near wait");need(!observe({18,0,0}).target&&!observe({18,0,0}).present,"remote radar");need(!observe({9,0,0},true,false).target&&!care.terminated(),"inactive grants follow or erases association");need(observe({9,0,0}).target.has_value(),"body reunion failed");
 need(!observe({9,0,0},true,true,true).target,"direct ignored");need(!observe({9,0,0},true,true,false,true).target,"player goal ignored");need(!observe({9,0,0},true,true,false,false,true).target,"urgent needs ignored");need(!observe({9,2.01,0}).present,"vertical knowledge");
 HeroSim intent;auto target=*observe({9,0,0}).target;need(!HeroDestination::submit(intent,{9,0,0},target,false)&&!intent.goal(),"unsupported path admitted");need(HeroDestination::submit(intent,{9,0,0},target,true),"supported follow submit");HeroDestination::update(intent,{9,0,0},0,.1,true,true,true);need(!HeroDestination::active(intent),"direct failed cancellation");
 adult.alive=false;need(!observe({9,0,0}).target&&care.terminated(),"dead parent still controls");adult.alive=true;need(!observe({9,0,0}).target,"dead parent resurrected ownership");need(!care.bindBirth(1,HeroSpecies::Longstride,LifeStage::Hatchling,{3.5,0,0},replacement),"replacement after death");need(!care.observe(2,LifeStage::Hatchling,{9,0,0},true,true,false,false,false,{replacement}).target,"new hero adopted");
 LongstrideCare missing;need(missing.bindBirth(1,HeroSpecies::Longstride,LifeStage::Hatchling,{3.5,0,0},adult),"second bind");need(!missing.observe(1,LifeStage::Hatchling,{9,0,0},true,true,false,false,false,{replacement}).target&&missing.terminated(),"missing parent retarget");
 // Existing registry remains the sole clock/contact owner; actual parent keeps urgent drinking despite close child.
 std::vector<HabitatSite> sites{{{0,0,0},false,true,{1}},{{4,0,0},true,false,{0}}};Population p(42,1001,sites,1);auto snap=p.snapshot();auto&a=snap.actors[0];a.id=77;a.species=HeroSpecies::Longstride;a.calendarAge=7000;a.stage=LifeStage::Adult;a.site=0;a.target=0;a.position={0,0,0};a.activity=Activity::Drink;a.hunger=.1;a.thirst=.8;a.fatigue=.1;a.isResting=false;p.restore(snap);
 ResourceLedgerDto ledger{{{100,ResourceKind::Creek,10,1},{200,ResourceKind::Shrub,10,0}},{{90,100,1}}};std::uint64_t next=100;engine::NativePopulationRegistry host(p,ledger,{{77,90}},{{0,100,{0,0,0}},{1,200,{4,0,0}}},next);const auto bindings=host.sessions();BodyAwareness context{{1,0,0},{},77,3,true,true};host.advance({1,2},true,context,true);const auto after=host.snapshot();need(after.actors[0].id==77&&after.actors[0].calendarAge==7002,"parent identity/clock changed");need(host.sessions()==bindings,"session binding reset");need(after.actors[0].thirst<.8&&host.ledger().resources[0].consumedQuantity>1,"parent urgent contact suppressed");need(host.ledger().sessions[0].sessionId==90&&host.ledger().sessions[0].amount>1,"old cumulative key lost");auto copy=host.registry();need(copy.restoreContinuation(host.continuation()),"snapshot restore invalid");
 std::cout<<"LONGSTRIDE_CARE_REVIEW_OK actualadult bind-once; Small unchanged; direct/playergoal/needs; body-only separation/reunion; dead/missing/no retarget/no N adoption; supported intention; sole registry clock/current binding and urgent shared contact history\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
